export function el(tag, className, text) { const node=document.createElement(tag); if(className) node.className=className; if(text!==undefined) node.textContent=text; return node; }
export function button(text, className, action) { const b=el('button',className,text); b.type='button'; b.addEventListener('click',action); return b; }
export function link(text, href, className='') { const a=el('a',className,text); a.href=href; return a; }
export function announce(message) { document.getElementById('announcement').textContent=message; }
export function focusHeading(container) { const heading=container.querySelector('h1,h2'); if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});} }
export function practiceFrame(host, current, total, label) { host.replaceChildren(); const shell=el('div','practice-shell'); const top=el('div','practice-top'); top.append(el('span','',label),el('span','',`${current} of ${total}`)); const progress=el('div','progress'); progress.setAttribute('role','progressbar'); progress.setAttribute('aria-label','Progress'); progress.setAttribute('aria-valuemin','0'); progress.setAttribute('aria-valuemax',String(total)); progress.setAttribute('aria-valuenow',String(current)); const fill=el('span');fill.style.width=`${current/total*100}%`;progress.append(fill);const body=el('div','practice-body');shell.append(top,progress,body);host.append(shell);return body; }
export function optionsList(options, selected, correct, onSelect) { const list=el('div','options'); options.forEach((option,i)=>{const b=button('','option',()=>onSelect(option.id));b.append(el('span','letter',String.fromCharCode(65+i)),el('span','',option.text));if(selected===option.id)b.classList.add('selected');if(correct){b.disabled=true;if(option.id===correct)b.classList.add('correct');else if(option.id===selected)b.classList.add('incorrect');}b.setAttribute('aria-pressed',String(selected===option.id));list.append(b);});return list; }
export function recommendations(host, ids, scams, openArticle) { const row=el('div','recommendations'); [...new Set(ids)].forEach(id=>{const topic=scams.find(s=>s.id===id);if(topic)row.append(button(topic.title,'',()=>openArticle(topic)));});host.append(row); }
